/**
 * SEO 组件
 *
 * 多语言：hrefLang 传 'en' / 'de'；canonical 与 og:url 自动带对应语言前缀。
 * 不传 hrefLang 时按英文处理（向后兼容所有既有调用点）。
 *
 * @author 恒哥
 */
import React from 'react';
import { Helmet } from 'react-helmet';
import { useStaticQuery, graphql } from 'gatsby';
import {
  PRODUCT_NAME,
  PRODUCT_NAME_FULL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_URL,
  SHOPIFY_INSTALL_PAGE_PATH,
  SITE_URL,
} from '../../constants/brand';
import { DEFAULT_LOCALE, LOCALES, localePath, resolveLocale } from '../../i18n/config';

export default function SEO({
  title,
  description,
  image,
  pathname,
  ogTitle,
  noindex = false,
  hrefLang = DEFAULT_LOCALE,
}) {
  const { site } = useStaticQuery(
    graphql`
      query {
        site {
          siteMetadata {
            title
            description
            siteUrl
            author
          }
        }
      }
    `
  );

  const { title: defaultTitle, description: defaultDescription, siteUrl } = site.siteMetadata;

  // pathname 传的是**英文视角**的路径（页面里写的都是 /pricing/ 这种），
  // 统一在这里加语言前缀 —— 页面作者不必关心自己在哪个语言版本里。
  const { basePath } = resolveLocale(pathname || '/');
  const localeCfg = LOCALES[hrefLang] || LOCALES[DEFAULT_LOCALE];
  const localizedPath = localePath(basePath, hrefLang);

  const seo = {
    title: title ? `${title} | ${defaultTitle}` : defaultTitle,
    description: description || defaultDescription,
    url: `${siteUrl}${localizedPath}`,
    ogTitle: ogTitle || title || defaultTitle, // og:title 使用原始标题，不包含后缀
  };

  const htmlLang = localeCfg.htmlLang;
  const ogLocale = localeCfg.ogLocale;
  // og:locale:alternate 是逗号分隔的其它语言版本
  const alternateLocales = Object.keys(LOCALES)
    .filter((c) => c !== hrefLang)
    .map((c) => LOCALES[c].ogLocale)
    .join(',');
  const hreflangLinks = Object.keys(LOCALES).map((c) => ({
    hreflang: LOCALES[c].htmlLang,
    href: `${siteUrl}${localePath(basePath, c)}`,
  }));
  const defaultPathForDefaultLocale = localePath(basePath, DEFAULT_LOCALE);

  const defaultImage = `${siteUrl}/favicon/favicon.png`;
  const robotsContent = noindex
    ? 'noindex, nofollow'
    : 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1';

  // JSON-LD 结构化数据
  const organizationSchema = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "Organization",
    "name": "Whaleal",
    "url": siteUrl,
    "logo": defaultImage,
    "description": defaultDescription,
    "sameAs": [SHOPIFY_APP_STORE_URL, SHOPIFY_APP_URL]
  });

  const softwareSchema = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    "name": PRODUCT_NAME,
    "alternateName": PRODUCT_NAME_FULL,
    "applicationCategory": "BusinessApplication",
    "operatingSystem": "Shopify",
    "offers": {
      "@type": "Offer",
      "price": "0",
      "priceCurrency": "USD",
      "availability": "https://schema.org/InStock"
    },
    "description": seo.description,
    "url": `${SITE_URL}${SHOPIFY_INSTALL_PAGE_PATH}`,
    "downloadUrl": SHOPIFY_APP_STORE_URL,
    "author": {
      "@type": "Organization",
      "name": "Whaleal",
      "url": siteUrl
    }
  });

  const websiteSchema = pathname === '/' ? JSON.stringify({
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: 'Whaleal',
    url: siteUrl,
    description: defaultDescription,
    publisher: {
      '@type': 'Organization',
      name: 'Whaleal',
      logo: defaultImage,
    },
  }) : null;

  return (
    <Helmet>
      <html lang={htmlLang} />
      <title>{seo.title}</title>
      <meta name="description" content={seo.description} />
      <meta name="robots" content={robotsContent} />
      <meta name="googlebot" content={robotsContent} />
      <meta name="theme-color" content="#1a3a5c" />
      <meta property="og:locale" content={ogLocale} />
      <meta property="og:locale:alternate" content={alternateLocales} />
      <link rel="icon" type="image/svg+xml" href="/favicon/favicon.svg" />
      <link rel="icon" type="image/png" sizes="48x48" href="/favicon/favicon-48.png" />
      <link rel="icon" type="image/png" sizes="32x32" href="/favicon/favicon-32.png" />
      <link rel="apple-touch-icon" sizes="180x180" href="/favicon/apple-touch-icon.png" />
      <link rel="manifest" href="/site.webmanifest" />
      <meta property="og:title" content={seo.ogTitle} />
      <meta property="og:description" content={seo.description} />
      <meta property="og:url" content={seo.url} />
      <meta property="og:site_name" content="Whaleal" />
      <meta property="og:type" content="website" />
      <meta property="og:image" content={image || defaultImage} />
      <meta property="og:image:width" content="512" />
      <meta property="og:image:height" content="512" />
      <meta property="og:image:alt" content="Whaleal — Shopify e-commerce apps" />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={seo.title} />
      <meta name="twitter:description" content={seo.description} />
      <meta name="twitter:image" content={image || defaultImage} />
      {!noindex && <link rel="canonical" href={seo.url} />}
      {/* hreflang：告诉搜索引擎同一页面的各语言版本，避免多语言互相「抢」排名。
          英文保持原路径（prefix 为空），德语带 /de 前缀。x-default 指向英文。 */}
      {hreflangLinks.map((l) => (
        <link key={l.hreflang} rel="alternate" hrefLang={l.hreflang} href={l.href} />
      ))}
      <link rel="alternate" hrefLang="x-default" href={`${siteUrl}${defaultPathForDefaultLocale}`} />
      <script type="application/ld+json">{organizationSchema}</script>
      <script type="application/ld+json">{softwareSchema}</script>
      {websiteSchema && <script type="application/ld+json">{websiteSchema}</script>}
    </Helmet>
  );
}

